"やり直す\",\"Ctrl+Y\"],[\"-\"],[\"cut\",\"切り取り\",\"Ctrl+X\"],[\"copy\",\"コピー\",\"Ctrl+C\"],[\"paste\",\"貼り付け\",\"Ctrl+V\"],[\"-\"],[\"find\",\"検索\",\"Ctrl+F\"],[\"replace\",\"置換\",\"Ctrl+H\"],[\"select\",\"すべて選択\",\"Ctrl+A\"],[\"date\",\"日時の挿入\",\"F5\"]],view:[[\"wrap\",\"右端で折り返す\",\"\"],[\"-\"],[\"zin\",\"拡大\",\"Ctrl++\"],[\"zout\",\"縮小\",\"Ctrl+-\"],[\"zreset\",\"標準サイズ\",\"Ctrl+0\"],[\"-\"],[\"theme\",\"テーマ切替\",\"\"]],help:[[\"about\",\"このアプリについて\",\"\"]]};\nfunction closeMenu(){menu.hidden=true;menuState=\"\";document.querySelectorAll(\"[data-menu]\").forEach(b=>b.classList.remove(\"active\"));}\nfunction openMenu(n,button){if(menuState===n){closeMenu();return;}menuState=n;menu.replaceChildren();for(const [id,label,key]of menus[n]){if(id===\"-\"){const s=document.createElement(\"div\");s.className=\"sep\";menu.append(s);continue;}const b=document.createElement(\"button\"),x=document.createElement(\"span\"),k=document.createElement(\"span\");x.textContent=(id===\"wrap\"&&wrap?\"✓ \":\"\")+label;k.textContent=key||\"\";k.className=\"shortcut\";b.append(x,k);b.onclick=()=>{closeMenu();commands[id]();};menu.append(b);}menu.style.left=Math.max(4,Math.min(innerWidth-270,button.getBoundingClientRect().left))+\"px\";menu.hidden=false;document.querySelectorAll(\"[data-menu]\").forEach(b=>b.classList.toggle(\"active\",b===button));}\ndocument.querySelectorAll(\"[data-menu]\").forEach(b=>b.onclick=()=>openMenu(b.dataset.menu,b));document.addEventListener(\"pointerdown\",e=>{if(!menu.contains(e.target)&&!e.target.closest(\"[data-menu]\"))closeMenu();});\ndocument.addEventListener(\"keydown\",e=>{if(e.key===\"Escape\"){closeMenu();$(\"finder\").hidden=true;return;}if(e.key===\"F5\"&&!e.ctrlKey){e.preventDefault();commands.date();return;}if(!(e.ctrlKey||e.metaKey)||e.altKey)return;const k=e.key.toLowerCase();\n if(k===\"s\"){e.preventDefault();(e.shiftKey?commands.savepc:commands.save)();}else if(k===\"z\"){e.preventDefault();undo(e.shiftKey);}else if(k===\"y\"){e.preventDefault();undo(true);}\n else if(k===\"n\"){e.preventDefault();commands.new();}else if(k===\"o\"){e.preventDefault();commands.open();}else if(k===\"f\"){e.preventDefault();commands.find();}else if(k===\"h\"){e.preventDefault();commands.replace();}\n else if(k===\"p\"){e.preventDefault();commands.print();}else if(k===\"w\"){e.preventDefault();remove(current);}else if(k===\"tab\"){e.preventDefault();if(docs.length){const i=docs.findIndex(d=>d.id===current);select(docs[(i+(e.shiftKey?docs.length-1:1))%docs.length].id);}}\n else if(k===\"+\"||k===\"=\"){e.preventDefault();commands.zin();}else if(k===\"-\"){e.preventDefault();commands.zout();}else if(k===\"0\"){e.preventDefault();commands.zreset();}});\n$(\"historybtn\").onclick=()=>{const d=doc();if(!d||!connected)return;if(d.dirty||d.pending){msg(\"保存完了後に履歴を開いてください\");save(d);return;}send({type:\"history\",id:d.id,client});};\n$(\"historyclose\").onclick=()=>$(\"historydialog\").close();\n// Mobile toolbar is intentionally tiny: no extra mode or second editor screen.\nmobileDocs.addEventListener(\"change\",()=>select(mobileDocs.value));\nconst drawer=$(\"mobile-drawer\"), more=$(\"mmore\");\nfunction toggleDrawer(open){drawer.hidden=!open;more.setAttribute(\"aria-expanded\",String(open));}\n$(\"mundo\").onclick=()=>undo();\n$(\"mredo\").onclick=()=>undo(true);\n$(\"mfind\").onclick=()=>search();\n$(\"msave\").onclick=()=>commands.save();\nmore.onclick=()=>toggleDrawer(drawer.hidden);\n$(\"mobile-toolbar\").addEventListener(\"pointerdown\",e=>{\n if(e.target.closest(\"#mundo,#mredo,#msave\"))e.preventDefault();\n});\ndrawer.querySelectorAll(\"[data-mobile-action]\").forEach(b=>b.onclick=()=>{\n toggleDrawer(false);\n switch(b.dataset.mobileAction){\n  case \"new\":create();break;\n  case \"open\":picker.click();break;\n  case \"cloudopen\":cloudOpen();break;\n  case \"savepc\":pcSave(true);break;\n  case \"rename\":commands.rename();break;\n  case \"replace\":search(true);break;\n  case \"history\":$(\"historybtn\").click();break;\n  case \"wrap\":commands.wrap();break;\n  case \"theme\":commands.theme();break;\n  case \"keyboard\":editor.blur();break;\n  case \"close\":remove(current);break;\n }\n});\ndocument.addEventListener(\"pointerdown\",e=>{\n if(!drawer.hidden && !drawer.contains(e.target) && !more.contains(e.target))toggleDrawer(false);\n});\nfunction syncVisualViewport(){\n if(!mobile()){document.documentElement.style.removeProperty(\"--viewport-height\");document.documentElement.style.removeProperty(\"--viewport-top\");return;}\n const vv=window.visualViewport;\n document.documentElement.style.setProperty(\"--viewport-height\",Math.max(180,Math.round(vv?.height||innerHeight))+\"px\");\n document.documentElement.style.setProperty(\"--viewport-top\",Math.round(vv?.offsetTop||0)+\"px\");\n}\nif(window.visualViewport){\n visualViewport.addEventListener(\"resize\",syncVisualViewport);\n visualViewport.addEventListener(\"scroll\",syncVisualViewport);\n}\nwindow.addEventListener(\"resize\",()=>{syncVisualViewport();opts();});\nsyncVisualViewport();\nwindow.addEventListener(\"beforeunload\",()=>{remember();backup();});document.addEventListener(\"visibilitychange\",()=>{if(!document.hidden&&ws?.readyState!==WebSocket.OPEN)connect();});\ntry{const x=JSON.parse(localStorage.getItem(CACHE)||\"null\");if(Array.isArray(x?.closedIds))for(const id of x.closedIds)closedTabs.add(id);if(x?.docs?.length){docs=x.docs.filter(d=>d&&typeof d.text===\"string\").slice(0,100).map(d=>({...fresh(d.name,d.text),id:d.id,shadow:d.shadow||\"\",revision:d.revision||0,created:!!d.created,dirty:!!d.dirty,locked:!!d.locked,renamePending:!!d.renamePending,pos:d.pos||0}));current=x.current;}}catch(e){}\nif(!docs.length){docs=[fresh()];docs[0].dirty=false;}\nif(!docs.some(d=>d.id===current))current=docs[0].id;\nopts();show();connect();\n})();";

function response(value,status=200){return new Response(JSON.stringify(value),{status,headers:{"Content-Type":"application/json","Cache-Control":"no-store"}})}
function validId(x){return typeof x==="string"&&/^[a-zA-Z0-9-]{8,80}$/.test(x)}
function spanDiff(a,b){let i=0;while(i<a.length&&i<b.length&&a[i]===b[i])i++;let j=0;while(j<a.length-i&&j<b.length-i&&a[a.length-1-j]===b[b.length-1-j])j++;return {at:i,del:a.length-i-j,ins:b.slice(i,b.length-j)}}
function applySpan(a,b){return a.slice(0,b.at)+b.ins+a.slice(b.at+b.del)}
function mergeText(base,mine,theirs){if(mine===base)return theirs;if(theirs===base)return mine;const a=spanDiff(base,mine),b=spanDiff(base,theirs);let i=a.at;if(a.at>=b.at+b.del)i+=b.ins.length-b.del;else if(a.at+a.del<=b.at){}else if(a.del===0&&b.del===0&&a.at===b.at)i+=b.ins.length;else return null;return applySpan(theirs,{...a,at:i})}
export class NotepadRoom{
 constructor(ctx,env){this.ctx=ctx;this.env=env;this.serial=Promise.resolve();}
 queue(fn){const next=this.serial.then(fn,fn);this.serial=next.catch(e=>console.error("NotepadRoom serial",e));return next;}
 send(ws,x){try{ws.send(JSON.stringify(x))}catch(e){}}
 everyone(x){for(const ws of this.ctx.getWebSockets())this.send(ws,x);}
 async list(){const v=await this.env.DB.prepare("SELECT id,name,content,revision,updated_at,name_locked FROM documents WHERE deleted=0 ORDER BY updated_at DESC LIMIT 100").all();return v.results||[];}
 async get(id){return this.env.DB.prepare("SELECT id,name,content,revision,updated_at,name_locked FROM documents WHERE id=? AND deleted=0").bind(id).first();}
 async fetch(r){
  if(r.headers.get("Upgrade")!=="websocket")return response({error:"upgrade required"},426);
  const pair=new WebSocketPair();const [client,server]=Object.values(pair);this.ctx.acceptWebSocket(server);
  try{this.send(server,{type:"hello",docs:await this.list()});}catch(e){this.send(server,{type:"error",error:"DB unavailable"});server.close(1011,"DB unavailable");}
  return new Response(null,{status:101,webSocket:client});
 }
 async webSocketMessage(ws,text){
  if(typeof text!=="string"||text.length>1100000){this.send(ws,{type:"error",error:"message too large"});return;}
  let m;try{m=JSON.parse(text)}catch(e){return;}
  if(!validId(m.id)||!["create","edit","delete","history","restore"].includes(m.type)){this.send(ws,{type:"error",error:"invalid request"});return;}
  await this.queue(async()=>{try{await this.process(ws,m)}catch(e){console.error("NotepadRoom",e);this.send(ws,{type:"error",id:m.id,error:"処理に失敗しました"});}});
 }
 async process(ws,m){
  const db=this.env.DB;
  if(m.type==="history"){const r=await db.prepare("SELECT revision,name,saved_at,length(content) AS length FROM history WHERE doc_id=? ORDER BY revision DESC LIMIT 60").bind(m.id).all();this.send(ws,{type:"history",id:m.id,history:r.results||[]});return;}
  if(m.type==="create"){
    if(typeof m.name!=="string"||!m.name.length||m.name.length>255||typeof m.content!=="string"||m.content.length>500000){this.send(ws,{type:"error",id:m.id,error:"文書のサイズまたは名前が不正です"});return;}
    const exists=await this.get(m.id);if(exists){this.send(ws,{type:"conflict",doc:exists});return;}
    const size=await db.prepare("SELECT COUNT(*) AS n FROM documents WHERE deleted=0").first();if(size.n>=100){this.send(ws,{type:"error",id:m.id,error:"文書は100件までです"});return;}
    const rr=await db.batch([
      db.prepare("INSERT INTO documents(id,name,content,revision,name_locked) VALUES(?,?,?,1,?)").bind(m.id,m.name,m.content,m.locked===true?1:0),
      db.prepare("INSERT INTO history(doc_id,revision,name,content) VALUES(?,1,?,?)").bind(m.id,m.name,m.content)
    ]);
    if(rr[0].meta.changes!==1){this.send(ws,{type:"error",id:m.id,error:"作成できませんでした"});return;}
    this.everyone({type:"state",doc:await this.get(m.id),seq:m.seq,client:m.client});return;
  }
  let d=await this.get(m.id);
  if(!d){this.send(ws,{type:"error",id:m.id,error:"文書が存在しません"});return;}
  if(m.type==="delete"){
   if(d.revision!==m.revision){this.send(ws,{type:"conflict",doc:d});return;}
   const r=await db.prepare("UPDATE documents SET deleted=1 WHERE id=? AND revision=?").bind(m.id,m.revision).run();
   if(r.meta.changes===1)this.everyone({type:"deleted",id:m.id});return;
  }
  if(m.type==="restore"){
   if(m.revision!==d.revision){this.send(ws,{type:"conflict",doc:d});return;}
   const h=await db.prepare("SELECT name,content FROM history WHERE doc_id=? AND revision=?").bind(m.id,m.from).first();
   if(!h){this.send(ws,{type:"error",id:m.id,error:"履歴が見つかりません"});return;}
   m.base=d.content;m.content=h.content;m.name=h.name;m.forceName=true;
  }
  if(typeof m.name!=="string"||m.name.length<1||m.name.length>255||typeof m.content!=="string"||m.content.length>500000||typeof m.base!=="string"||m.base.length>500000||!Number.isSafeInteger(m.revision)){
   this.send(ws,{type:"error",id:m.id,error:"更新が不正です"});return;
  }
  let content=m.content;
  if(m.revision!==d.revision){content=mergeText(m.base,content,d.content);if(content===null){this.send(ws,{type:"conflict",doc:d});return;}}
  else if(m.base!==d.content){this.send(ws,{type:"conflict",doc:d});return;}
  const locked=d.name_locked===1||m.locked===true?1:0;
  const target=m.forceName===true?m.name:d.name_locked===1?d.name:m.name;
  if(content===d.content&&target===d.name&&locked===d.name_locked){this.send(ws,{type:"state",doc:d,seq:m.seq,client:m.client});return;}
  if(content.length>500000){this.send(ws,{type:"error",id:m.id,error:"更新後のサイズが大きすぎます"});return;}
  const next=d.revision+1;
  const out=await db.batch([
   db.prepare("UPDATE documents SET name=?,content=?,revision=?,name_locked=?,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=? AND revision=? AND deleted=0").bind(target,content,next,locked,m.id,d.revision),
   db.prepare("INSERT INTO history(doc_id,revision,name,content) VALUES(?,?,?,?)").bind(m.id,next,target,content),
   db.prepare("DELETE FROM history WHERE doc_id=? AND revision NOT IN (SELECT revision FROM history WHERE doc_id=? ORDER BY revision DESC LIMIT 60)").bind(m.id,m.id)
  ]);
  if(out[0].meta.changes!==1){this.send(ws,{type:"conflict",doc:await this.get(m.id)});return;}
  this.everyone({type:"state",doc:await this.get(m.id),seq:m.seq,client:m.client});
 }
 async webSocketClose(ws,code,reason){try{ws.close(code,reason)}catch(e){}}
 async webSocketError(ws){try{ws.close(1011,"internal error")}catch(e){}}
}

export default {async fetch(request,env){
const u=new URL(request.url);if(u.hostname!=='notepad.karin-lab.com')return new Response('Not Found',{status:404});
if(u.pathname==='/socket'){if(request.headers.get('Upgrade')!=='websocket')return response({error:'Upgrade required'},426);if(request.headers.get('Origin')!=='https://notepad.karin-lab.com')return response({error:'Origin forbidden'},403);return env.ROOM.get(env.ROOM.idFromName('karin-notepad-room')).fetch(request);}
if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method Not Allowed',{status:405});
const assets={'/':[HTML,'text/html; charset=utf-8'],'/index.html':[HTML,'text/html; charset=utf-8'],'/style.css':[CSS,'text/css; charset=utf-8'],'/app.js':[JS,'application/javascript; charset=utf-8']};
const a=assets[u.pathname];if(!a)return new Response('Not Found',{status:404});
return new Response(request.method==='HEAD'?null:a[0],{headers:{'Content-Type':a[1],'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Frame-Options':'DENY','Content-Security-Policy':"default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self' wss://notepad.karin-lab.com; img-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'"}});
}};